effects.fragmentShader:
#extension GL_OES_EGL_image_external : require
precision mediump float;
#ifdef GL_FRAGMENT_PRECISION_HIGH
precision highp float;
#endif

varying vec2 vTexCoord;
uniform samplerExternalOES uTexture;
uniform sampler2D uMaskTexture;
uniform vec2 uTexelSize;
uniform float uTime;
uniform float uIntensity;
uniform float uAura;

float hash(vec2 p) { return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453); }
float vnoise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  return mix(mix(hash(i), hash(i + vec2(1.0, 0.0)), f.x),
             mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), f.x), f.y);
}
float fbm(vec2 p) { return 0.6 * vnoise(p) + 0.4 * vnoise(p * 2.1 + 7.3); }
float maskAt(vec2 uv) { return texture2D(uMaskTexture, uv).a; }

void main() {
  vec3 base = texture2D(uTexture, vTexCoord).rgb;
  float aspect = uTexelSize.y / uTexelSize.x;
  vec2 A = vec2(aspect, 1.0);
  vec2 p = vTexCoord * A;
  float mask = maskAt(vTexCoord);
  float t = uTime;

  vec2 q = p * 5.0 + vec2(0.0, -t * 0.9);
  vec2 warp = vec2(fbm(q) - 0.5, fbm(q + 11.7) - 0.5);
  float rot = hash(vTexCoord * 91.7) * 0.785398;

  float c1 = 0.0;
  float c2 = 0.0;
  float c3 = 0.0;
  float c4 = 0.0;
  for (int i = 0; i < 8; i++) {
    float a = float(i) * 0.785398 + rot;
    vec2 d = vec2(cos(a), sin(a));
    c1 += maskAt((p + d * 0.007) / A);
    c2 += maskAt((p + d * 0.022 + warp * 0.012) / A);
    c3 += maskAt((p + d * 0.050 + warp * 0.035) / A);
    c4 += maskAt((p + d * 0.100 + warp * 0.070) / A);
  }
  c1 /= 8.0;
  c2 /= 8.0;
  c3 /= 8.0;
  c4 /= 8.0;

  float outside = 1.0 - mask;
  float rimOut = outside * smoothstep(0.0, 0.5, c1);
  float rimIn = mask * (1.0 - smoothstep(0.55, 1.0, c1));
  float glowA = outside * c2;
  float glowB = outside * c3;
  float glowC = outside * c4;
  float n = fbm(p * vec2(7.0, 4.0) + vec2(0.0, -t * 0.6));
  float wisp = glowC * (0.08 + 1.7 * smoothstep(0.45, 0.72, n));
  float pulse = uAura * (0.85 + 0.6 * uIntensity + 0.05 * sin(t * 2.0));

  vec3 core = vec3(0.92, 0.80, 1.0);
  vec3 violet = vec3(0.55, 0.15, 1.0);
  vec3 magenta = vec3(0.95, 0.25, 0.95);
  vec3 aura = core * (rimOut * 1.6 + rimIn * 0.8)
            + violet * (glowA * 0.95 + glowB * 0.5)
            + magenta * (wisp * 1.25 + glowB * 0.18);

  vec2 sg = floor(p / 0.022);
  float sh = hash(sg);
  vec2 sc = (sg + 0.5 + (vec2(hash(sg + 1.7), hash(sg + 5.3)) - 0.5) * 0.5) * 0.022;
  float tw = pow(0.5 + 0.5 * sin(t * 3.0 + sh * 40.0), 6.0);
  float spark = step(0.965, sh) * tw * smoothstep(0.016, 0.0, distance(p, sc)) * smoothstep(0.08, 0.5, glowB + glowC);
  aura += vec3(0.9, 0.75, 1.0) * spark * 1.6;
  aura *= pulse;

  vec3 bg = base * vec3(0.36, 0.25, 0.60);
  vec3 fg = base * vec3(0.95, 0.82, 1.08) + violet * rimIn * 0.35 * pulse + magenta * mask * c3 * 0.18 * pulse;
  vec3 col = mix(bg, fg, mask);
  vec3 glow = clamp(1.0 - exp(-aura * 1.15), 0.0, 1.0);
  col = 1.0 - (1.0 - col) * (1.0 - glow);
  gl_FragColor = vec4(col, 1.0);
}

#extension GL_OES_EGL_image_external : require
precision mediump float;

    varying vec2 vTexCoord;
    uniform samplerExternalOES uTexture;
    uniform float uBeatEnergy; // 0..1, decays each frame, spikes on a beat
    void main() {
      vec4 base = texture2D(uTexture, vTexCoord);
      float vig = smoothstep(0.95, 0.2, distance(vTexCoord, vec2(0.5)));
      vec3 pulseColor = vec3(0.9, 0.3, 1.0);
      gl_FragColor = vec4(base.rgb + pulseColor * uBeatEnergy * vig * 0.6, base.a);
    }

effects.vertexShader:
uniform mat4 uTexMatrix;
uniform vec2 uShakeOffset;
attribute vec4 aPosition;
attribute vec4 aTexCoord;
varying mediump vec2 vTexCoord;
void main() {
  gl_Position = vec4(aPosition.xy + uShakeOffset, aPosition.z, aPosition.w);
  vTexCoord = (uTexMatrix * aTexCoord).xy;
}

effects.fragmentShader:
precision mediump float;
varying vec2 vTexCoord;
uniform samplerExternalOES uTexture;
void main() { gl_FragColor = texture2D(uTexture, vTexCoord); }

#extension GL_OES_EGL_image_external : require
precision mediump float;

    varying vec2 vTexCoord;
    uniform samplerExternalOES uTexture;
    uniform vec4 uFaceBox;
    uniform float uIntensity; // 0..1, how strong the bulge is
    void main() {
      vec2 center = vec2((uFaceBox.x + uFaceBox.z) * 0.5, (uFaceBox.y + uFaceBox.w) * 0.5);
      float faceSize = max(uFaceBox.z - uFaceBox.x, uFaceBox.w - uFaceBox.y);
      float influenceRadius = faceSize * 2.2;
      vec2 rel = vTexCoord - center;
      float d = length(rel);
      float t = clamp(d / influenceRadius, 0.0, 1.0);
      // Bulge near the center (magnify), gentle inverse compression at the
      // radius edge so the surrounding body doesn't just look "cut" —
      // conserves roughly the same on-screen area, which is what keeps
      // this readable as "big head" rather than "floating zoomed circle."
      float bulge = mix(1.0 - uIntensity * 0.6, 1.0 + uIntensity * 0.15, smoothstep(0.0, 1.0, t));
      vec2 warped = center + rel * bulge;
      gl_FragColor = texture2D(uTexture, warped);
    }

effects.vertexShader:
uniform float uZoom;
attribute vec4 aPosition;
attribute vec4 aTexCoord;
varying mediump vec2 vTexCoord;
void main() {
  gl_Position = vec4(aPosition.xy / uZoom, aPosition.z, aPosition.w);
  vTexCoord = aTexCoord.xy;
}

effects.fragmentShader:
precision mediump float;
varying vec2 vTexCoord;
uniform sampler2D uFrozenTexture;
vec2 hash2(vec2 p) {
  vec2 q = vec2(dot(p, vec2(127.1, 311.7)), dot(p, vec2(269.5, 183.3)));
  return fract(sin(q) * 43758.5453);
}
float frostCrystals(vec2 uv, float scale) {
  vec2 p = uv * scale;
  vec2 cell = floor(p);
  float d1 = 8.0; float d2 = 8.0;
  for (int y = -1; y <= 1; y++) for (int x = -1; x <= 1; x++) {
    vec2 neighbor = vec2(float(x), float(y));
    vec2 point = neighbor + hash2(cell + neighbor);
    float d = distance(p - cell, point);
    if (d < d1) { d2 = d1; d1 = d; } else if (d < d2) { d2 = d; }
  }
  return smoothstep(0.06, 0.0, d2 - d1);
}
void main() {
  vec4 src = texture2D(uFrozenTexture, vTexCoord);
  float luma = dot(src.rgb, vec3(0.299, 0.587, 0.114));
  vec3 desat = mix(src.rgb, vec3(luma), 0.55);
  vec3 iceTint = desat * vec3(0.75, 0.88, 1.05);
  float crystalsFine = frostCrystals(vTexCoord, 38.0);
  float crystalsCoarse = frostCrystals(vTexCoord + 5.2, 14.0) * 0.6;
  float crystals = clamp(crystalsFine + crystalsCoarse, 0.0, 1.0);
  vec3 outColor = iceTint + vec3(0.9, 0.96, 1.0) * crystals * 0.5;
  gl_FragColor = vec4(outColor, src.a);
}

#extension GL_OES_EGL_image_external : require
precision mediump float;

    varying vec2 vTexCoord;
    uniform samplerExternalOES uTexture;
    uniform float uTime;
    float hash1(float n) { return fract(sin(n) * 43758.5453); }
    void main() {
      vec4 base = texture2D(uTexture, vTexCoord);
      vec3 glow = vec3(0.0);
      for (int i = 0; i < 10; i++) {
        float fi = float(i);
        vec2 seed = vec2(hash1(fi * 12.9898), hash1(fi * 78.233 + 4.0));
        float speed = 0.02 + hash1(fi * 3.7) * 0.03;
        vec2 pos = fract(seed + vec2(hash1(fi * 5.3) - 0.5, -uTime * speed));
        float size = 0.05 + hash1(fi * 9.1) * 0.09;
        float d = distance(vTexCoord, pos);
        float orb = smoothstep(size, 0.0, d) * 0.5;
        vec3 hue = hash1(fi * 2.1) > 0.5 ? vec3(1.0, 0.75, 0.4) : vec3(0.5, 0.7, 1.0);
        glow += hue * orb;
      }
      gl_FragColor = vec4(base.rgb + glow, base.a);
    }

#extension GL_OES_EGL_image_external : require
precision mediump float;

    varying vec2 vTexCoord;
    uniform samplerExternalOES uTexture;
    void main() {
      vec3 c = texture2D(uTexture, vTexCoord).rgb;
      float luma = dot(c, vec3(0.299, 0.587, 0.114));
      c = mix(c, c * 1.08 + 0.02, smoothstep(0.0, 0.4, luma));
      c = c / (c + vec3(0.06));
      vec3 shadowTint = vec3(0.02, 0.03, 0.05);
      vec3 highlightTint = vec3(0.04, 0.02, -0.01);
      c += shadowTint * (1.0 - luma) + highlightTint * luma;
      float vig = smoothstep(0.95, 0.35, distance(vTexCoord, vec2(0.5)));
      c *= mix(0.82, 1.0, vig);
      gl_FragColor = vec4(clamp(c, 0.0, 1.0), 1.0);
    }

#extension GL_OES_EGL_image_external : require
precision mediump float;

    varying vec2 vTexCoord;
    uniform samplerExternalOES uTexture;
    uniform vec2 uBoomCenter;
    uniform float uBoomEnergy;
    uniform vec2 uParticlePos[24];
    uniform float uParticleRot[24];
    uniform float uParticleLife[24];
    uniform float uParticleColorIdx[24];
    uniform int uParticleCount;
    vec3 paletteColor(float idx) {
      if (idx < 0.5) return vec3(1.0, 0.9, 0.5);
      if (idx < 1.5) return vec3(1.0, 0.6, 0.3);
      return vec3(1.0, 0.95, 0.8);
    }
    void main() {
      vec4 base = texture2D(uTexture, vTexCoord);
      float d = distance(vTexCoord, uBoomCenter);
      float flash = exp(-d * d * 60.0) * uBoomEnergy;
      float maxRadius = 0.22;
      float ring = 0.0;
      for (int i = 0; i < 2; i++) {
        float echoEnergy = clamp(uBoomEnergy - float(i) * 0.25, 0.0, 1.0);
        float radius = (1.0 - echoEnergy) * maxRadius;
        float ringWidth = 0.012 + (1.0 - echoEnergy) * 0.008;
        ring += smoothstep(ringWidth, 0.0, abs(d - radius)) * echoEnergy * (1.0 - float(i) * 0.35);
      }
      vec3 addColor = vec3(1.0, 0.95, 0.8) * flash + vec3(1.0, 0.85, 0.5) * ring;
      for (int i = 0; i < 24; i++) {
        if (i >= uParticleCount) break;
        vec2 toP = vTexCoord - uParticlePos[i];
        float rad = radians(uParticleRot[i]);
        vec2 local = vec2(toP.x * cos(rad) + toP.y * sin(rad), -toP.x * sin(rad) + toP.y * cos(rad));
        float inShape = smoothstep(0.010, 0.006, abs(local.x)) * smoothstep(0.010, 0.006, abs(local.y));
        addColor += paletteColor(uParticleColorIdx[i]) * inShape * uParticleLife[i];
      }
      gl_FragColor = vec4(base.rgb + addColor, base.a);
    }

#extension GL_OES_EGL_image_external : require
precision mediump float;

    varying vec2 vTexCoord;
    uniform samplerExternalOES uTexture;
    uniform float uIntensity; // stillness amount 0..1
    float luma(vec3 c) { return dot(c, vec3(0.299, 0.587, 0.114)); }
    void main() {
      vec4 src = texture2D(uTexture, vTexCoord);
      float gray = luma(src.rgb);
      vec3 desaturated = vec3(gray);
      gl_FragColor = vec4(mix(src.rgb, desaturated, uIntensity), src.a);
    }

#extension GL_OES_EGL_image_external : require
precision mediump float;
#ifdef GL_FRAGMENT_PRECISION_HIGH
precision highp float;
#endif

varying vec2 vTexCoord;
uniform samplerExternalOES uTexture;
uniform vec2 uTexelSize;
uniform vec2 uIrisLeft;
uniform vec2 uIrisRight;
uniform vec2 uEyeOpen;
uniform vec4 uFaceBox;
uniform float uPower;
uniform float uEyeSize;
uniform float uTimeSec;

// x,y,z = glow colour to ADD, w = how much to REPLACE the real eye (0..1)
vec4 demonEye(vec2 p, vec2 o, float open, float faceW, float seed) {
  if (open < 0.01) return vec4(0.0);
  vec2 q = p - o;
  float ew = faceW * 0.108 * uEyeSize;
  float eh = faceW * 0.056 * uEyeSize * (0.18 + 0.82 * open);
  float d = length(q / vec2(ew, eh));
  float pulse = 0.93 + 0.07 * sin(uTimeSec * 5.0 + seed);

  float body = 1.0 - smoothstep(0.80, 1.0, d);
  float core = exp(-dot(q, q) / (ew * ew * 0.16));
  vec3 eyeCol = mix(vec3(0.85, 0.03, 0.01), vec3(1.0, 0.13, 0.05), exp(-d * d * 1.3));
  eyeCol += vec3(1.0, 0.68, 0.62) * core * 0.9;
  eyeCol *= pulse;

  float glowIn = 1.0 - smoothstep(0.9, 3.0, d);
  float glowOut = exp(-dot(q, q) / (faceW * faceW * 0.0150));
  float flare = exp(-(q.y * q.y) / (faceW * faceW * 0.00018)) * exp(-abs(q.x) / (faceW * 0.15));
  vec3 glow = vec3(1.0, 0.10, 0.04) * (glowIn * 0.65 + glowOut * 0.28) * pulse
            + vec3(1.0, 0.35, 0.18) * flare * 0.35;

  vec3 add = (eyeCol * body * 0.55 + glow) * open;
  return vec4(add, body * 0.92 * open);
}

void main() {
  vec3 base = texture2D(uTexture, vTexCoord).rgb;
  float aspect = uTexelSize.y / uTexelSize.x;
  vec2 A = vec2(aspect, 1.0);
  vec2 p = vTexCoord * A;
  float faceW = max((uFaceBox.z - uFaceBox.x) * aspect, 0.05);

  vec4 l = demonEye(p, uIrisLeft * A, uEyeOpen.x, faceW, 0.0);
  vec4 r = demonEye(p, uIrisRight * A, uEyeOpen.y, faceW, 2.7);

  float rep = clamp(l.w + r.w, 0.0, 1.0);
  vec3 eyeFill = vec3(0.0);
  float wsum = l.w + r.w;
  if (wsum > 0.001) eyeFill = (l.rgb * l.w + r.rgb * r.w) / wsum;
  vec3 col = mix(base, eyeFill * 1.6, rep);
  vec3 add = 1.0 - exp(-(l.rgb + r.rgb) * uPower);
  vec3 outc = 1.0 - (1.0 - col) * (1.0 - add);
  gl_FragColor = vec4(outc, 1.0);
}

#extension GL_OES_EGL_image_external : require
precision mediump float;

    varying vec2 vTexCoord;
    uniform samplerExternalOES uTexture;
    uniform sampler2D uMaskTexture;
    uniform vec2 uTexelSize;
    uniform float uIntensity; // normalized audio amplitude 0..1
    void main() {
      vec4 src = texture2D(uTexture, vTexCoord);
      float mask = texture2D(uMaskTexture, vTexCoord).a;
      vec3 bloom = vec3(0.0);
      float total = 0.0;
      for (int x = -2; x <= 2; x++) {
        for (int y = -2; y <= 2; y++) {
          vec2 offset = vec2(float(x), float(y)) * uTexelSize * 3.0;
          float w = 1.0 / (1.0 + float(x * x + y * y));
          bloom += texture2D(uTexture, vTexCoord + offset).rgb * w;
          total += w;
        }
      }
      bloom /= total;
      bloom.r = mix(bloom.r, texture2D(uTexture, vTexCoord + uTexelSize * 2.0).r, 0.3);
      bloom.b = mix(bloom.b, texture2D(uTexture, vTexCoord - uTexelSize * 2.0).b, 0.3);
      float bloomAmount = (0.5 + 0.7 * uIntensity) * (1.0 - mask);
      vec3 outColor = mix(src.rgb, bloom, bloomAmount);
      gl_FragColor = vec4(outColor, src.a);
    }

#extension GL_OES_EGL_image_external : require
precision mediump float;

    varying vec2 vTexCoord;
    uniform samplerExternalOES uTexture;
    uniform vec4 uFaceBox;
    uniform float uIntensity; // turn-speed magnitude 0..1
    void main() {
      vec2 center = vec2((uFaceBox.x + uFaceBox.z) * 0.5, (uFaceBox.y + uFaceBox.w) * 0.5);
      vec2 toPixel = vTexCoord - center;
      vec4 color = vec4(0.0);
      float totalWeight = 0.0;
      const int SAMPLES = 8;
      for (int i = 0; i < SAMPLES; i++) {
        float scale = 1.0 - uIntensity * 0.05 * float(i);
        vec2 sampleUv = center + toPixel * scale;
        float weight = 1.0 - float(i) / float(SAMPLES);
        color += texture2D(uTexture, sampleUv) * weight;
        totalWeight += weight;
      }
      gl_FragColor = vec4(color.rgb / totalWeight, 1.0);
    }

#extension GL_OES_EGL_image_external : require
precision mediump float;

    varying vec2 vTexCoord;
    uniform samplerExternalOES uTexture;
    uniform float uDropEnergy; // 1 at the moment of a drop, decays over ~0.8s
    void main() {
      vec2 center = vec2(0.5);
      vec2 dir = vTexCoord - center;
      vec3 sum = vec3(0.0);
      const int SAMPLES = 6;
      for (int i = 0; i < SAMPLES; i++) {
        float t = float(i) / float(SAMPLES - 1);
        vec2 uv = center + dir * (1.0 - uDropEnergy * 0.25 * t);
        sum += texture2D(uTexture, uv).rgb;
      }
      vec3 blurred = sum / float(SAMPLES);
      vec3 flashed = blurred + vec3(1.0) * uDropEnergy * 0.4;
      gl_FragColor = vec4(flashed, 1.0);
    }

#extension GL_OES_EGL_image_external : require
precision mediump float;

    varying vec2 vTexCoord;
    uniform samplerExternalOES uTexture;
    uniform vec3 uColorA;
    uniform vec3 uColorB;
    uniform float uTime;
    uniform float uPulseSpeed;
    float luma(vec3 c) { return dot(c, vec3(0.299, 0.587, 0.114)); }
    void main() {
      vec4 src = texture2D(uTexture, vTexCoord);
      float l = luma(src.rgb);
      float phase = 0.5 + 0.5 * sin(uTime * uPulseSpeed * 6.28318);
      vec3 low = mix(uColorA, uColorB, step(0.5, phase));
      vec3 high = mix(uColorB, uColorA, step(0.5, phase));
      vec3 duotone = mix(low, high, l);
      gl_FragColor = vec4(duotone, src.a);
    }

#extension GL_OES_EGL_image_external : require
precision mediump float;
#ifdef GL_FRAGMENT_PRECISION_HIGH
precision highp float;
#endif

varying vec2 vTexCoord;
uniform samplerExternalOES uTexture;
uniform vec2 uTexelSize;
uniform vec2 uIrisLeft;
uniform vec2 uIrisRight;
uniform vec2 uGaze;
uniform vec2 uEyeOpen;
uniform vec4 uFaceBox;
uniform vec2 uGazeSign;
uniform float uPower;
uniform float uTimeSec;

vec3 laserEye(vec2 p, vec2 o, vec2 g, vec2 splay, float open, float faceW) {
  if (open < 0.01) return vec3(0.0);
  vec2 d = g + splay;
  d = d / max(length(d), 0.0001);
  vec2 q = p - o;
  float along = dot(q, d);
  float perp = abs(q.x * d.y - q.y * d.x);
  float r = length(q);
  float t = max(along, 0.0) / faceW;

  float w = faceW * (0.011 + 0.007 * min(t, 3.0));
  float x = perp / w;
  float core = exp(-x * x);
  float glow = exp(-x * x / 16.0);
  float halo = exp(-x * x / 140.0);
  float start = smoothstep(-0.01 * faceW, 0.04 * faceW, along);
  float decay = 1.0 / (1.0 + 0.22 * t);
  float flick = 0.95 + 0.05 * sin(uTimeSec * 50.0 + t * 9.0);
  vec3 beam = (vec3(1.0, 0.93, 0.86) * core * 1.7
             + vec3(1.0, 0.11, 0.05) * glow * 1.15
             + vec3(1.0, 0.05, 0.02) * halo * 0.40) * start * decay * flick;

  float e1 = r / (faceW * 0.030);
  float e2 = r / (faceW * 0.075);
  float e3 = r / (faceW * 0.22);
  float streak = exp(-(q.y * q.y) / (faceW * faceW * 0.00022)) * exp(-abs(q.x) / (faceW * 0.16));
  vec3 eye = vec3(1.0, 0.88, 0.78) * exp(-e1 * e1) * 2.0
           + vec3(1.0, 0.13, 0.05) * exp(-e2 * e2) * 1.3
           + vec3(1.0, 0.06, 0.03) * exp(-e3 * e3) * 0.28
           + vec3(1.0, 0.20, 0.12) * streak * 0.55;

  return (beam + eye) * open;
}

void main() {
  vec4 base = texture2D(uTexture, vTexCoord);
  float aspect = uTexelSize.y / uTexelSize.x;
  vec2 A = vec2(aspect, 1.0);
  vec2 p = vTexCoord * A;
  float faceW = max((uFaceBox.z - uFaceBox.x) * aspect, 0.05);
  vec2 g = uGaze * uGazeSign;
  vec3 add = laserEye(p, uIrisLeft * A, g, vec2(-0.10, 0.16), uEyeOpen.x, faceW)
           + laserEye(p, uIrisRight * A, g, vec2(0.10, 0.16), uEyeOpen.y, faceW);
  add = 1.0 - exp(-add * uPower);
  vec3 outc = 1.0 - (1.0 - base.rgb) * (1.0 - add);
  gl_FragColor = vec4(outc, base.a);
}

#extension GL_OES_EGL_image_external : require
precision mediump float;
#ifdef GL_FRAGMENT_PRECISION_HIGH
precision highp float;
#endif

varying vec2 vTexCoord;
uniform samplerExternalOES uTexture;
uniform vec2 uTexelSize;
uniform vec4 uFaceBox;
uniform float uProgress;
uniform vec2 uParticlePos[24];
uniform float uParticleRot[24];
uniform float uParticleLife[24];
uniform float uParticleColorIdx[24];
uniform int uParticleCount;

vec2 hash2(vec2 p) {
  vec2 q = vec2(dot(p, vec2(127.1, 311.7)), dot(p, vec2(269.5, 183.3)));
  return fract(sin(q) * 43758.5453);
}

vec3 palette(float i) {
  if (i < 0.5) return vec3(1.0, 0.35, 0.55);
  if (i < 1.5) return vec3(1.0, 0.85, 0.20);
  if (i < 2.5) return vec3(0.20, 0.85, 1.0);
  if (i < 3.5) return vec3(1.0, 0.55, 0.15);
  if (i < 4.5) return vec3(0.70, 0.35, 1.0);
  return vec3(0.40, 1.0, 0.45);
}

void main() {
  vec3 base = texture2D(uTexture, vTexCoord).rgb;
  float aspect = uTexelSize.y / uTexelSize.x;
  vec2 A = vec2(aspect, 1.0);
  vec2 p = vTexCoord * A;
  float pr = clamp(uProgress, 0.0, 1.0);
  float env = sin(3.14159265 * pr);
  vec3 col = base;
  vec2 fc = vec2((uFaceBox.x + uFaceBox.z) * 0.5 * aspect, (uFaceBox.y + uFaceBox.w) * 0.5);
  float faceW = max((uFaceBox.z - uFaceBox.x) * aspect, 0.05);
  float faceH = max(uFaceBox.w - uFaceBox.y, 0.05);

  if (env > 0.001) {
    vec2 q = p - fc;
    float d = length(q / vec2(faceW * 0.52, faceH * 0.58));
    float inFace = 1.0 - smoothstep(0.92, 1.12 + 0.25 * env, d);
    if (inFace > 0.001) {
      float c = faceW * 0.085;
      vec2 baseId = floor(p / c);
      float cover = 0.0;
      vec2 chipCC = vec2(0.0);
      float chipH = 0.0;
      for (int jy = -2; jy <= 2; jy++) {
        for (int jx = -2; jx <= 2; jx++) {
          vec2 id = baseId + vec2(float(jx), float(jy));
          vec2 cc = (id + 0.5) * c;
          vec2 h = hash2(id);
          vec2 dir = cc - fc;
          dir = dir / max(length(dir), 0.0001);
          vec2 disp = (dir * (0.25 + 0.75 * h.x) * 1.4 + (hash2(id + 3.1) - 0.5) * 0.6) * c * env;
          float ang = (h.y - 0.5) * 2.4 * env;
          vec2 rel = p - (cc + disp);
          float cs = cos(ang);
          float sn = sin(ang);
          vec2 loc = vec2(rel.x * cs + rel.y * sn, -rel.x * sn + rel.y * cs);
          float hw = c * 0.52 * (1.0 - 0.12 * env);
          float inside = (1.0 - smoothstep(hw - 0.0015, hw, abs(loc.x))) * (1.0 - smoothstep(hw - 0.0015, hw, abs(loc.y)));
          if (inside > cover) { cover = inside; chipCC = cc; chipH = h.x * 0.7 + h.y * 0.3; }
        }
      }
      vec3 src = texture2D(uTexture, chipCC / A).rgb;
      vec3 tint = palette(floor(chipH * 5.99));
      vec3 chipCol = mix(src, tint, 0.30 * env) * (0.9 + 0.35 * chipH);
      float lum = dot(src, vec3(0.299, 0.587, 0.114));
      chipCol = mix(vec3(lum), chipCol, 1.0 + 0.5 * env);
      vec3 mosaic = mix(base * 0.75, chipCol, cover);
      col = mix(base, mosaic, inFace * clamp(env * 1.6, 0.0, 1.0));
    }
  }

  for (int i = 0; i < 24; i++) {
    if (i >= uParticleCount) break;
    vec2 toP = (vTexCoord - uParticlePos[i]) * A;
    float rad = radians(uParticleRot[i]);
    vec2 loc = vec2(toP.x * cos(rad) + toP.y * sin(rad), -toP.x * sin(rad) + toP.y * cos(rad));
    float sz = faceW * 0.040;
    float shape = (1.0 - smoothstep(sz * 0.85, sz, abs(loc.x))) * (1.0 - smoothstep(sz * 0.5, sz * 0.6, abs(loc.y)));
    col = mix(col, palette(uParticleColorIdx[i]) * 1.15, shape * uParticleLife[i]);
  }
  gl_FragColor = vec4(col, 1.0);
}

